================================================================================
PART 1 — BUILD SCRIPT (Python 3.13, build time only). Produces dict.json.
================================================================================
Inputs already verified downloadable:
  jmdict-eng-common-3.6.2.json  (unzip of the release asset)
  deinflect.json                (Yomichan)
  ojlpt_n{1..5}.json            (OpenJLPT vocab)

# build_dict.py
import json, gzip, collections

BIT = {'adj-i':1, 'v1':2, 'v5':4, 'vk':8, 'vs':16, 'vz':32, 'iru':64}

# ---- 1. compile the deinflection table -------------------------------------
raw = json.load(open('deinflect.json', encoding='utf-8'))
rules = []
for reason, variants in raw.items():
    for r in variants:
        ri = 0
        for x in r['rulesIn']:  ri |= BIT[x]
        ro = 0
        for x in r['rulesOut']: ro |= BIT[x]
        rules.append([reason, r['kanaIn'], r['kanaOut'], ri, ro])
rules.sort(key=lambda x: -len(x[1]))
json.dump(rules, open('deinflect.json.out', 'w', encoding='utf-8'),
          ensure_ascii=False, separators=(',', ':'))
# -> 569 rules, 20,706 bytes raw / 3,607 gzip

# ---- 2. JLPT levels --------------------------------------------------------
jlpt = {}
for lv in [1, 2, 3, 4, 5]:            # N1 first so N5 wins on conflict
    for w in json.load(open(f'ojlpt_n{lv}.json', encoding='utf-8')):
        for key in (w.get('word'), w.get('reading')):
            if key: jlpt[key] = f'N{lv}'

# ---- 3. function words that must beat homograph noise ----------------------
FUNC = set('はがをにでともやのへねよかなさぞわしば')
FUNC |= {'です','ます','ある','いる','する','なる','これ','それ','あれ',
         'この','その','あの','から','まで','より','だけ','ほど','しか',
         'など','でも','のに','ので','ても','とか',
         '彼','私','僕','君','何','人','事','物','時','所','中','方',
         '上','下','前','後','日','年'}
LVL_BONUS = {'N5':30, 'N4':24, 'N3':18, 'N2':12, 'N1':6}

d = json.load(open('jmdict-eng-common-3.6.2.json', encoding='utf-8'))
entries = []
index = collections.defaultdict(list)

for w in d['words']:
    kanji = [k for k in w['kanji'] if 'sK' not in k['tags']]   # drop search-only
    kana  = [k for k in w['kana']  if 'sk' not in k['tags']]
    ktxt  = [k['text'] for k in kanji]
    rtxt  = [k['text'] for k in kana]

    pos, gl = [], []
    for s in w['sense'][:4]:                       # cap: 4 senses
        for p in s['partOfSpeech']:
            if p not in pos: pos.append(p)
        gl.append('; '.join(g['text'] for g in s['gloss'][:5]))   # cap: 5 glosses

    eid  = len(entries)
    head = ktxt[0] if ktxt else rtxt[0]
    lvl  = jlpt.get(head) or (jlpt.get(rtxt[0]) if rtxt else None)
    entries.append([';'.join(ktxt), ';'.join(rtxt),
                    ','.join(pos), '|'.join(gl), lvl or ''])

    def reading_for(ktext):
        """JMdict kana[].appliesToKanji tells us which reading goes with which
           kanji spelling. Resolving it here is free; doing it at runtime is not."""
        for ri, k in enumerate(kana):
            a = k.get('appliesToKanji') or ['*']
            if '*' in a or ktext in a: return ri
        return 0

    seen = set()
    for pi, k in enumerate(kanji):
        t = k['text']
        if t in seen: continue
        seen.add(t)
        sc = (0 if k.get('common') else 40) + pi * 3
        if lvl: sc -= LVL_BONUS[lvl]
        if t in FUNC: sc -= 100
        index[t].append([eid, reading_for(t), sc])
    for ri, k in enumerate(kana):
        t = k['text']
        if t in seen: continue
        seen.add(t)
        sc = (0 if k.get('common') else 40) + ri * 3
        if ktxt: sc += 25            # kana spelling of a word normally written in kanji
        if lvl: sc -= LVL_BONUS[lvl]
        if t in FUNC: sc -= 100
        index[t].append([eid, ri, sc])

for t in index:
    index[t].sort(key=lambda x: x[2])

# CRITICAL: two parallel arrays, not a keyed object (2-4x faster to load)
keys = sorted(index)
out = {'k': keys,
       'v': [[x for triple in index[k] for x in triple] for k in keys],  # flat triples
       'e': entries}
json.dump(out, open('dict.json', 'w', encoding='utf-8'),
          ensure_ascii=False, separators=(',', ':'))

b = open('dict.json', 'rb').read()
print(f'{len(entries)} entries, {len(keys)} surfaces, '
      f'{len(b)/1048576:.2f} MB raw, {len(gzip.compress(b,9))/1048576:.2f} MB gzip')
# measured -> 22640 entries, 46762 surfaces, 3.24 MB raw, 1.10 MB gzip


================================================================================
PART 2 — RUNTIME TOKENIZER (jp-lookup.js). Tested; numbers in Part 4.
================================================================================
Run this inside a Web Worker. Strip the `import fs` / `load()` at the bottom and
fetch() the two JSON files instead.

// ---------------------------------------------------------------------------
// Deinflection rule flags. These 7 bits are the entire type system.
// adj-i=1  v1=2  v5=4  vk=8  vs=16  vz=32  iru=64
// ---------------------------------------------------------------------------
export function posToRuleMask(ps){let m=0;for(const p of ps){
 if(p==='adj-i'||p==='adj-ix')m|=1; else if(p==='v1'||p==='v1-s')m|=2;
 else if(p.startsWith('v5'))m|=4; else if(p==='vk')m|=8;
 else if(p==='vs'||p==='vs-i'||p==='vs-s'||p==='vs-c')m|=16; else if(p==='vz')m|=32;}
 return m;}

export class Deinflector{
 constructor(rules){
  // Bucketing by the LAST char of kanaIn turns a 569-rule scan into ~20.
  this.byLast=new Map();
  for(const [reason,kIn,kOut,rIn,rOut] of rules){
   const L=kIn[kIn.length-1];
   let a=this.byLast.get(L); if(!a){a=[];this.byLast.set(L,a);}
   a.push({reason,kIn,kOut,rIn,rOut});}}

 /** BFS over the rule table. Returns every candidate dictionary form with the
  *  chain of reasons that produced it. rules===0 means "straight from the text,
  *  no constraint yet"; after one step it is the bitmask the entry must satisfy. */
 deinflect(src){
  const res=[{term:src,rules:0,reasons:null,d:0}];
  const seen=new Set([src+'\u0000'+0]);
  for(let i=0;i<res.length;i++){
   const n=res[i];
   if(n.d>=8) continue;                                    // depth guard
   const cands=this.byLast.get(n.term[n.term.length-1]); if(!cands) continue;
   for(const r of cands){
    if(n.rules!==0&&(n.rules&r.rIn)===0) continue;
    if(!n.term.endsWith(r.kIn)) continue;
    const L=n.term.length-r.kIn.length+r.kOut.length; if(L<=0) continue;
    const next=n.term.slice(0,n.term.length-r.kIn.length)+r.kOut;
    const key=next+'\u0000'+r.rOut; if(seen.has(key)) continue; seen.add(key);
    res.push({term:next,rules:r.rOut,reasons:{name:r.reason,prev:n.reasons},d:n.d+1});}}
  return res;}
}
const chain=r=>{const a=[];while(r){a.push(r.name);r=r.prev;}return a;};

const isKanji=c=>(c>='一'&&c<='鿿')||c==='々';
const isHira =c=>c>='ぁ'&&c<='ゟ';
const isKata =c=>(c>='ァ'&&c<='ヺ')||c==='ー';
const isDigit=c=>(c>='0'&&c<='9')||(c>='０'&&c<='９');
export const isJa=c=>isKanji(c)||isHira(c)||isKata(c)||c==='・';

// A JMdict exp/int entry ending in one of these is word+particle, not a word.
const TRAILING_PARTICLE=new Set(['は','が','を','に','で','と',
 'も','の','へ','や','か','ね','よ','わ','ぞ','な','さ']);

const COUNTERS=['時間','か月','ヶ月','年間','週間','人前','分間',
 'ページ','キロ','メートル','センチ','グラム','円','人','個','本','枚','冊',
 '匹','頭','台','杯','回','度','歳','才','番','階','丁目','時','分','秒','日','月','年','週','つ','名','件','軒'];

// Multi-word grammar / keigo patterns a word dictionary always mis-splits.
// Ship as data (grammar.json) so the grammar lessons and the reader share it.
// Grow this to ~300 entries — it is the highest-leverage file in the app.
export const PHRASES = {
 'させていただきます':['humble: I will (humbly) do','N3'],
 'させていただけますか':['humble request: may I …?','N2'],
 'させていただきたく存じます':['very humble: I would like to …','N1'],
 'ていただけますでしょうか':['very polite request: could you please …?','N2'],
 'ていただけませんか':['polite request: could you …?','N3'],
 'なければなりません':['must / have to','N4'],
 'なければならない':['must / have to','N4'],
 'なくてはいけない':['must / have to','N4'],
 'ことができます':['can / be able to','N4'],
 'ことができる':['can / be able to','N4'],
 'かもしれません':['might / maybe','N4'],
 'かもしれない':['might / maybe','N4'],
 'たほうがいい':['had better / should','N4'],
 'にもかかわらず':['in spite of','N2'],
 'わけにはいかない':['cannot (for social reasons)','N2'],
 'ざるを得ない':['have no choice but to','N1'],
 '恐れ入りますが':['keigo: I am sorry to trouble you, but','biz'],
 'お世話になっております':['keigo: thank you for your continued support','biz'],
 'よろしくお願いいたします':['keigo: thank you in advance','biz'],
 'ありがとうございます':['thank you','N5'],
 'ご承知おきください':['keigo: please be aware','biz'],
 'お手数をおかけしますが':['keigo: sorry for the trouble, but','biz'],
 'かしこまりました':['keigo: certainly (understood)','biz'],
};

export class JpDict{
 constructor(d,dein){
  this.phrases=new Map(Object.entries(PHRASES));
  this.phraseMax=Math.max(...[...this.phrases.keys()].map(k=>k.length));
  this.keys=d.k; this.e=d.e; this.d=dein;
  // Map from two parallel arrays — 2-4x faster than Object.entries()
  this.idx=new Map(); for(let n=0;n<d.k.length;n++) this.idx.set(d.k[n],d.v[n]);
  this.mask=this.e.map(r=>posToRuleMask(r[2]?r[2].split(','):[]));
  // Head-char scan cap. NOTE: a 2-char prefix prune here is WRONG and silently
  // breaks every deinflection (読ん is not a prefix of any key).
  this.maxLen=new Map();
  for(const k of this.keys){const c=k[0];const n=Math.min(k.length,14);
   if(!(this.maxLen.get(c)>=n)) this.maxLen.set(c,n);}
  this.MAXSCAN=14;}

 entry(id,ri,surface,score){
  const [k,r,p,g,lv]=this.e[id];
  const kanji=k?k.split(';'):[], kana=r?r.split(';'):[];
  return {id,kanji,kana,
   word: kanji.includes(surface)?surface:(kanji[0]||kana[0]),
   reading: kana[ri]||kana[0]||'',      // readingIdx, not kana[0]: は !== はね
   pos: p?p.split(','):[], senses: g?g.split('|'):[],
   jlpt: lv||null, score};}

 lookupExact(s){const post=this.idx.get(s); if(!post) return [];
  const out=[]; for(let n=0;n<post.length;n+=3) out.push(this.entry(post[n],post[n+1],s,post[n+2]));
  return out;}

 // A JMdict "expression"/"interjection" that is really word+particle
 // (今日は = konnichiwa) must not swallow the particle while segmenting.
 // Must check BOTH exp and int — こんにちは is tagged int, not exp.
 blocksSegmentation(ent,surface){
  if(!ent.pos.includes('exp')&&!ent.pos.includes('int')) return false;
  return TRAILING_PARTICLE.has(surface[surface.length-1]);}

 /** Strict longest-match, the Yomichan / 10ten strategy. Do NOT score across
  *  lengths — I tried it and 日本語 became 日|本|語, です became で|す. */
 lookupAt(text,pos,{segmenting=true}={}){
  const c0=text[pos];
  const cap=this.maxLen.get(c0);               // head char is never rewritten
  if(cap===undefined && !isDigit(c0)) return null;
  // A deinflected tail is at most 8 chars longer than the dict tail it replaces
  // (くありませんでした: 9 in, 1 out).
  const maxLen=Math.min(this.MAXSCAN,cap+8,text.length-pos);
  for(let len=maxLen;len>=1;len--){
   const surface=text.slice(pos,pos+len);
   const hits=[];
   for(const n of this.d.deinflect(surface)){
    const post=this.idx.get(n.term); if(!post) continue;
    const reasons=n.reasons?chain(n.reasons):[];
    for(let j=0;j<post.length;j+=3){
     const id=post[j];
     // an inflected match is only valid if the entry's POS permits it
     if(reasons.length>0){ if(n.rules===0) continue; if((this.mask[id]&n.rules)===0) continue; }
     const ent=this.entry(id,post[j+1],n.term,post[j+2]);
     ent.inflection=reasons; ent.dictForm=n.term;
     ent.rank=ent.score+reasons.length*8+(ent.pos.includes('exp')?16:0);
     hits.push(ent);}}
   if(!hits.length) continue;
   hits.sort((a,b)=>a.rank-b.rank);
   const seen=new Set(),cands=[];
   for(const h of hits){if(!seen.has(h.id)){seen.add(h.id);cands.push(h);}}
   if(segmenting && cands.every(c=>this.blocksSegmentation(c,surface))) continue;
   return {start:pos,end:pos+len,surface,candidates:cands};}
  return null;}

 /** Segment a line. Never fails: every character ends up in a tappable token. */
 tokenize(text){
  const out=[]; let i=0;
  while(i<text.length){
   const c=text[i];

   // non-Japanese run passes through
   if(!isJa(c)&&!isDigit(c)){let j=i;while(j<text.length&&!isJa(text[j])&&!isDigit(text[j]))j++;
    out.push({t:text.slice(i,j),kind:'other'}); i=j; continue;}

   // number (+ counter) is one token
   if(isDigit(c)){let j=i;while(j<text.length&&(isDigit(text[j])||text[j]==='.'||text[j]===','))j++;
    let ct=''; for(const x of COUNTERS){if(text.startsWith(x,j)){ct=x;break;}}
    out.push({t:text.slice(i,j)+ct,kind:'number',counter:ct}); i=j+ct.length; continue;}

   // (a) grammar / keigo phrase, longest first — before the dictionary
   let ph=null;
   for(let L=Math.min(this.phraseMax,text.length-i);L>=2;L--){
    const cand=text.slice(i,i+L);
    if(this.phrases.has(cand)){ph={t:cand,info:this.phrases.get(cand)};break;}}
   if(ph){const [gloss,lv]=ph.info;
    out.push({t:ph.t,kind:'phrase',gloss,jlpt:lv}); i+=ph.t.length; continue;}

   // (b) a katakana run is ONE word unless the dictionary covers all of it.
   //     スマートフォン must not become スマート + フォン.
   if(isKata(c)){
    let j=i;while(j<text.length&&(isKata(text[j])||text[j]==='・'))j++;
    const run=text.slice(i,j);
    const whole=this.idx.get(run);
    if(whole){
     const a=[]; for(let q=0;q<whole.length;q+=3) a.push(this.entry(whole[q],whole[q+1],run,whole[q+2]));
     a.sort((x,y)=>x.score-y.score);
     for(const x of a){x.inflection=[];x.dictForm=run;}
     out.push({t:run,kind:'word',hit:{start:i,end:j,surface:run,candidates:a}}); i=j; continue;}
    const km=this.lookupAt(text,i);
    if(km&&km.end===j){out.push({t:km.surface,kind:'word',hit:km}); i=km.end; continue;}
    out.push({t:run,kind:'katakana'}); i=j; continue;}   // still tappable

   // (c) normal dictionary longest-match
   const m=this.lookupAt(text,i);
   if(m){out.push({t:m.surface,kind:'word',hit:m}); i=m.end; continue;}

   // (d) unmatched kanji run -> probably a name; tap falls back to KANJIDIC
   if(isKanji(c)){let j=i;while(j<text.length&&isKanji(text[j])&&j-i<4)j++;
    out.push({t:text.slice(i,j),kind:'name?'}); i=j; continue;}
   out.push({t:c,kind:'unknown'}); i++;}
  return out;}
}

// ---------------------------------------------------------------------------
// FURIGANA: okurigana anchoring. No morphological analyzer needed.
// ---------------------------------------------------------------------------
const toHira=s=>s.replace(/[ァ-ヶ]/g,ch=>String.fromCharCode(ch.charCodeAt(0)-0x60));

export function furigana(word,reading){
 if(!reading) return [{t:word}];
 const r=toHira(reading), w=word, out=[]; let wi=0,ri=0;
 while(wi<w.length){
  if(!isKanji(w[wi])){
   // kana in the word must consume the same kana in the reading
   if(ri<r.length&&r[ri]===toHira(w[wi])){out.push({t:w[wi]});wi++;ri++;continue;}
   return [{t:w,r:reading}];}                       // bail: whole-word ruby
  let wj=wi; while(wj<w.length&&isKanji(w[wj]))wj++;
  const run=w.slice(wi,wj);
  let wk=wj; while(wk<w.length&&!isKanji(w[wk]))wk++;
  const tail=toHira(w.slice(wj,wk));                // okurigana after the run
  let rEnd;
  if(tail===''){rEnd=r.length;}
  // the +run.length offset is load-bearing: without it 取り引き mis-splits
  else{rEnd=r.indexOf(tail,ri+run.length); if(rEnd<0) return [{t:w,r:reading}];}
  if(rEnd<=ri) return [{t:w,r:reading}];
  out.push({t:run,r:r.slice(ri,rEnd)}); ri=rEnd; wi=wj;}
 if(ri!==r.length) return [{t:w,r:reading}];
 return out;}

/** Ruby for an INFLECTED surface. Naive alignment gives 起きて[おきる]; this
 *  strips the dropped dict tail off the reading first. */
export function furiganaInflected(surface,dictForm,dictReading){
 if(surface===dictForm) return furigana(surface,dictReading);
 let p=0; while(p<surface.length&&p<dictForm.length&&surface[p]===dictForm[p])p++;
 const dropped=dictForm.slice(p), added=surface.slice(p);
 const hr=toHira(dictReading);
 if(dropped && hr.endsWith(toHira(dropped))){
  const stemReading=hr.slice(0,hr.length-dropped.length);
  const stem=surface.slice(0,p);
  if(!stem) return [{t:surface}];
  const segs=furigana(stem,stemReading);
  return added?[...segs,{t:added}]:segs;}
 return [{t:surface}];}


